# Generated by scripts/build-deploy.sh — do not edit directly.
# setup-user-cursor.ps1 — Sets up Cursor CLI + dependencies on Windows
# Self-contained: User Rules content is embedded below. No repo or Drive needed.
# Safe to re-run — checks each step and skips what's already done.
#
# Does four things:
#   1. Installs ripgrep (rg) if not already present (required by Cursor CLI)
#   2. Installs Cursor CLI (agent command) if not already present
#   3. Writes ~/.cursor/cli-config.json (skips if already up to date)
#   4. Copies embedded User Rules to clipboard for pasting into Cursor Settings > Rules

# --- Logging ---
$logDir = Join-Path $env:LOCALAPPDATA "ai-tooling"
$logFile = Join-Path $logDir "deploy.log"
$scriptName = "setup-user-cursor"
$errors = 0

if (-not (Test-Path $logDir)) { New-Item -ItemType Directory -Path $logDir -Force | Out-Null }

function Log($msg) {
    $ts = (Get-Date).ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ssZ")
    $line = "[$ts] [$scriptName] $msg"
    Write-Host $line
    Add-Content -Path $logFile -Value $line
}
function LogOk($msg)    { Log "OK: $msg" }
function LogError($msg) { Log "ERROR: $msg"; $script:errors++ }
function LogWarn($msg)  { Log "WARN: $msg" }

# --- OS guard ---
if ($PSVersionTable.PSVersion.Major -ge 6 -and -not $IsWindows) {
    LogError "This script is for Windows. On macOS/Linux, use the .sh version."
    exit 1
}

# Helper: refresh PATH from registry (picks up winget installs in same session)
function Refresh-Path {
    $machinePath = [Environment]::GetEnvironmentVariable("Path", "Machine")
    $userPath = [Environment]::GetEnvironmentVariable("Path", "User")
    $env:Path = "$machinePath;$userPath"
}

$cursorDir = Join-Path $env:USERPROFILE ".cursor"
$cliConfig = Join-Path $cursorDir "cli-config.json"

# --- 1. ripgrep (rg) ---
Log "Step 1: ripgrep (rg)"

$rgCmd = Get-Command rg -ErrorAction SilentlyContinue
if ($rgCmd) {
    $rgVersion = (rg --version | Select-Object -First 1)
    LogOk "Already installed: $rgVersion"
} else {
    Log "Installing ripgrep via winget..."
    winget install BurntSushi.ripgrep.MSVC --accept-package-agreements --accept-source-agreements
    Refresh-Path
    $rgCmd = Get-Command rg -ErrorAction SilentlyContinue
    if ($rgCmd) {
        LogOk "Installed: $(rg --version | Select-Object -First 1)"
    } else {
        LogError "winget install completed but 'rg' not found in PATH (restart terminal)"
    }
}

# --- 2. Cursor CLI (agent) ---
Log "Step 2: Cursor CLI (agent)"

$agentCmd = Get-Command agent -ErrorAction SilentlyContinue
if ($agentCmd) {
    $agentVersion = agent --version
    LogOk "Already installed: $agentVersion"
} else {
    Log "Installing Cursor CLI..."
    Invoke-Expression (Invoke-RestMethod 'https://cursor.com/install?win32=true')
    $agentCmd = Get-Command agent -ErrorAction SilentlyContinue
    if ($agentCmd) {
        LogOk "Installed: $(agent --version)"
    } else {
        LogError "Cursor CLI install completed but 'agent' not found in PATH (restart terminal)"
    }
}

# --- 3. cli-config.json ---
Log "Step 3: cli-config.json"

$expectedConfig = @'
{
  "version": 1,
  "editor": {
    "vimMode": false
  },
  "permissions": {
    "allow": [],
    "deny": []
  }
}
'@

if (-not (Test-Path $cursorDir)) {
    New-Item -ItemType Directory -Path $cursorDir -Force | Out-Null
    Log "Created $cursorDir"
}

if (Test-Path $cliConfig) {
    $existingConfig = (Get-Content -Path $cliConfig -Raw).TrimEnd()
    if ($existingConfig -eq $expectedConfig) {
        LogOk "Already up to date: $cliConfig"
    } else {
        Set-Content -Path $cliConfig -Value $expectedConfig -Encoding UTF8 -NoNewline
        LogOk "Updated: $cliConfig"
    }
} else {
    Set-Content -Path $cliConfig -Value $expectedConfig -Encoding UTF8 -NoNewline
    LogOk "Created: $cliConfig"
}

# --- 4. User Rules ---
Log "Step 4: User Rules (embedded)"

# --- Embedded User Rules (from shared/cursor-rules/user-rules.md) ---
$userRulesContent = @'
# Cursor User Rules

**How to apply:** Copy everything below the `---` line and paste it into
**Cursor Settings > Rules** on each machine.

Source of truth: `shared/cursor-rules/user-rules.md` in the ai-tooling repo.
The `setup-user-cursor` script copies this to your clipboard automatically.

---

## Identity

- Name: Jose
- Git: `Jose <jose@nobul.tech>`
- Company: Nobul

## Code Style Defaults

- Prefer simple, minimal solutions over clever abstractions
- Use type hints in Python; use TypeScript over plain JS
- Favor standard library over third-party when the gap is small
- Write CLI tools with `--help` support

## Cross-Platform Awareness

- I work on both Windows 11 and macOS -- both are first-class
- Use forward slashes and `$HOME`/`~` in path references when possible
- Projects live in git repos under `~/repos/` (macOS) / `C:\repos\` (Windows)
- Some legacy projects still on Google Drive (`G:\My Drive\` / `~/Google Drive/My Drive/`) -- migrate to git repos over time

## Git Conventions

- Always set local git identity (`Jose <jose@nobul.tech>`) before first commit in a new repo
- Commit messages: imperative mood, concise
- Branch naming: `feature/`, `fix/`, `docs/` prefixes

## Communication Style

- Be concise -- skip filler and caveats
- Explain the "why" behind non-obvious decisions
- Don't add docstrings, comments, or type annotations to code you didn't change
'@

if (-not $env:AITOOLS_DEPLOY) {
    Set-Clipboard -Value $userRulesContent
    LogOk "Copied User Rules to clipboard"
    Log "Paste into: Cursor Settings > Rules"
} else {
    LogOk "User Rules embedded and ready"
}

# --- Exit ---
if ($errors -gt 0) {
    Log "FAILED with $errors error(s). See log: $logFile"
    exit 1
} else {
    Log "COMPLETED successfully"
    exit 0
}
